import { useRulesText } from "@/shared/ability-text"

/**
 * Rules-text resolution for raid-boss abilities and traits, from the en-only game-data namespaces
 * generated by `scripts/generate-raid-boss-i18n.mjs`: one `raidBossAbilityText/<id>` namespace (file)
 * per ability, and the whole, small `raidBossTraitText`. The served `raid-bosses` dataset carries ids
 * only; the `{[variable]}` tokens in a description are resolved against these tables per progression
 * step. Referenced abilities without text are listed in `raidBossAbilityTextGaps` and never requested.
 */

export type RaidBossAbilityTextEntry = {
  description: string
  variables: Record<string, (string | number)[]>
  constants: Record<string, string>
  /** Variable names multiplied by the rarity factor when rendered. */
  scaled: string[]
}

export type RaidBossTraitTextEntry = {
  description: string
  styledName: string
  variables: Record<string, (string | number)[]>
}

/** The rules text of the given abilities, fetched per ability after the detail view paints. */
export function useRaidBossAbilityText(abilityIds: readonly string[]) {
  return useRulesText<RaidBossAbilityTextEntry>({
    namespace: "raidBossAbilityText",
    gaps: "raidBossAbilityTextGaps",
    ids: abilityIds,
  })
}

/** The trait rules text, loaded with the traits panel. */
export function useRaidBossTraitText() {
  return useRulesText<RaidBossTraitTextEntry>({
    namespace: "raidBossTraitText",
  })
}
